// 1. Define Catalog: Google Drive PDF File IDs vs. Web Search topics
const catalog = [
  // --- PDF SOURCES (Replace with your own Google Drive File IDs) ---
  {
    sourceName: "Study-Guide-Part-1.pdf",
    type: "pdf",
    fileId: "YOUR_GOOGLE_DRIVE_FILE_ID_1",
