    type: "pdf",
    fileId: "YOUR_GOOGLE_DRIVE_FILE_ID_2",
    category: "Advanced Concepts"
  },

  // --- WEB SEARCH TOPICS (Powered by Tavily + Gemini) ---
  {
    sourceName: "System Architecture & Design Patterns",
    type: "web",
    searchTopic: "Distributed systems, caching strategies, load balancing, and fault tolerance best practices",
    category: "Architecture & Design"
  },
  {
