    searchTopic: "Zero trust security, IAM least privilege, encryption at rest and in transit, and API security",
    category: "Security & Governance"
  },
  {
    sourceName: "Agile Delivery & Product Operations",
    type: "web",
    searchTopic: "Iterative product discovery, sprint planning, backlog prioritization, and stakeholder alignment",
    category: "Product & Delivery"
  }
];

// 2. Select a random item from the catalog
const randomIndex = Math.floor(Math.random() * catalog.length);
const selectedSource = catalog[randomIndex];

// 3. Return standardized payload
return [
  {
    json: {
      timestamp: new Date().toISOString(),
      ...selectedSource
    }
  }
];

const catalogData = $('Catalog').item.json;
const extractData = $input.item.json;

const rawText = extractData.text || '';
const totalPages = extractData.numpages || 1;
const charsPerPage = Math.max(1500, Math.floor(rawText.length / totalPages));

// Helper function to detect TOC, front matter, or low-value pages
function isSkippableChunk(text) {
  if (!text || text.trim().length < 350) return true;

  const lower = text.toLowerCase();

  // 1. Explicit front/back matter headings
  const skipKeywords = [
    'table of contents',
    'list of figures',
    'list of tables',
    'isbn-13',
    'isbn-10',
    'all rights reserved',
    'complimentary iiba',
    'acknowledgments',
    'acknowledgements',
    'glossary',
    'bibliography'
  ];
  if (skipKeywords.some(kw => lower.includes(kw))) return true;

  // 2. TOC dot-leader pattern (e.g., "1.2 Purpose ........ 14")
  const dotLeaders = (text.match(/\.{4,}/g) || []).length;
  if (dotLeaders >= 4) return true;

  // 3. High ratio of lines ending in page numbers
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  const linesEndingInPageNum = lines.filter(l => /\s+\d{1,4}$/.test(l)).length;
  if (lines.length > 8 && (linesEndingInPageNum / lines.length) > 0.35) return true;

  return false;
}

// Pick a random page chunk (skipping first 3% front matter and last 5% back matter)
let actualPageNumber = 1;
let selectedPageText = '';

const minPage = Math.max(1, Math.floor(totalPages * 0.03));
const maxPage = Math.max(minPage + 1, Math.floor(totalPages * 0.95));

for (let attempt = 0; attempt < 25; attempt++) {
  const candidatePage = Math.floor(Math.random() * (maxPage - minPage)) + minPage;
  const startChar = (candidatePage - 1) * charsPerPage;
  const endChar = Math.min(rawText.length, startChar + charsPerPage + 400); // +400 buffer to finish paragraph

  let chunk = rawText.slice(startChar, endChar);

  // Snap start and end to clean paragraph/sentence boundaries
  const firstNewline = chunk.indexOf('\n');
  if (firstNewline > 0 && firstNewline < 200) {
    chunk = chunk.slice(firstNewline + 1);
  }
  const lastPeriod = chunk.lastIndexOf('.');
  if (lastPeriod > chunk.length * 0.6) {
    chunk = chunk.slice(0, lastPeriod + 1);
  }

  chunk = chunk.trim();

  if (!isSkippableChunk(chunk) || attempt === 24) {
    actualPageNumber = candidatePage;
    selectedPageText = chunk;
    break;
  }
}

// Randomize quiz format
const randomValue = Math.random();
let selectedFormat = "Single Choice";
if (randomValue > 0.7) {
  selectedFormat = "Short Answer";
} else if (randomValue > 0.4) {
  selectedFormat = "Multiple Choice";
}

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      sourceType: catalogData.type || "pdf",
      sourceName: catalogData.sourceName,
      category: catalogData.category,
      referencePage: actualPageNumber,
      extractedContent: selectedPageText,
      sourceCitation: `${catalogData.sourceName} - Page ~${actualPageNumber}`,
      targetFormat: selectedFormat
    }
  }
];

