// 1. Join all text parts from Gemini output
const parts = $input.item.json.content?.parts || [];
const rawText = parts.map(part => part.text || '').join('');

// 2. Strip markdown backticks
const cleanJsonString = rawText
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// 3. Parse JSON string
const quizData = JSON.parse(cleanJsonString);

// 4. Extract explanation intro vs quote if present
let introText = quizData.explanationIntro || "According to industry standards:";
let rawQuote = quizData.explanationQuote || quizData.explanation;

if (!quizData.explanationQuote && quizData.explanation) {
  const quoteMatch = quizData.explanation.match(/'([^']+)'|"([^"]+)"/);
  if (quoteMatch) {
    rawQuote = quoteMatch[1] || quoteMatch[2];
    introText = quizData.explanation.replace(quoteMatch[0], '').trim();
  }
}

// 5. Collect ALL reference URLs (from JSON fields + Gemini groundingMetadata)
const urlSet = new Set();

const addUrl = (val) => {
  if (!val) return;
  if (Array.isArray(val)) {
    val.forEach(addUrl);
  } else if (typeof val === 'object' && val.url) {
    urlSet.add(val.url.trim());
  } else if (typeof val === 'string') {
    const matches = val.match(/https?:\/\/[^\s)>\]]+/g);
    if (matches) matches.forEach(u => urlSet.add(u.trim()));
  }
};

addUrl(quizData.referenceUrls);
addUrl(quizData.references);
addUrl(quizData.webReferences);
addUrl(quizData.sourceUrl);
addUrl(quizData.source);

// Also check Gemini's native search grounding chunks if present
const chunks = $input.item.json.groundingMetadata?.groundingChunks || [];
chunks.forEach(c => {
  if (c.web?.uri) urlSet.add(c.web.uri.trim());
});

const allUrls = [...urlSet];
const webReferences = allUrls.length
  ? allUrls.map(u => `• <${u}>`).join('\n')
  : '';

return [
  {
    json: {
      ...quizData,
      explanationIntro: introText,
      explanationQuote: rawQuote,
      referenceUrls: allUrls,
      webReferences
    }
  }
];

const parts = $input.item.json.content.parts || [];
const rawText = parts.map(part => part.text || '').join('');

const cleanJsonString = rawText
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

const quizData = JSON.parse(cleanJsonString);

// Extract quote inside single/double quotes if present, or format explanation
let introText = "According to the source documentation:";
let rawQuote = quizData.explanation;

const quoteMatch = quizData.explanation.match(/'([^']+)'|"([^"]+)"/);
if (quoteMatch) {
  rawQuote = quoteMatch[1] || quoteMatch[2];
  introText = quizData.explanation.replace(quoteMatch[0], '').trim();
}

return [
  {
    json: {
      ...quizData,
      explanationIntro: introText,
      explanationQuote: rawQuote
    }
  }
];

const staticData = $getWorkflowStaticData('global');
if (!staticData.quizzes) {
  staticData.quizzes = {};
}

// Thread ID returned by whichever Post Quiz node just ran
const threadId = $input.item.json.id;

// Dynamically grab quiz data from whichever branch executed (PDF vs. Web)
let quiz = null;
try {
  if ($('JSON Parsing1').isExecuted) {
    quiz = $('JSON Parsing1').item.json;
  }
} catch (e) {}

if (!quiz) {
  try {
    if ($('JSON Parsing').isExecuted) {
      quiz = $('JSON Parsing').item.json;
    }
  } catch (e) {}
}

if (!quiz) {
  throw new Error('Could not find parsed quiz data from either JSON Parsing or JSON Parsing1.');
}

// Safely resolve fallback citation if PDF branch ran
let fallbackCitation = 'Web Research';
try {
  if ($('Random Page').isExecuted) {
    fallbackCitation = $('Random Page').item.json.sourceCitation;
  }
} catch (e) {}

const cleanQuote = (quiz.explanationQuote || quiz.explanation || '').replace(/^\*+|\*+$/g, '').trim();
const formattedExplanation = quiz.explanationIntro
  ? `${quiz.explanationIntro}\n> ${cleanQuote}`
  : `> ${cleanQuote}`;

// Normalize webReferences whether it is an array of URLs or already a formatted string
const normalizedWebRefs = Array.isArray(quiz.webReferences)
  ? quiz.webReferences.map(u => `• <${u}>`).join('\n')
  : (typeof quiz.webReferences === 'string' && quiz.webReferences.trim()
      ? quiz.webReferences
      : (Array.isArray(quiz.referenceUrls) ? quiz.referenceUrls.map(u => `• <${u}>`).join('\n') : ''));

const resolvedCitation = quiz.sourceCitation || fallbackCitation;

// Store the answer key indexed by threadId
staticData.quizzes[threadId] = {
  question: quiz.question,
  targetFormat: quiz.targetFormat,
  correctAnswer: quiz.correctAnswer,
  explanation: formattedExplanation,
  webReferences: normalizedWebRefs,
  sourceCitation: resolvedCitation,
  createdAt: Date.now(),
  publicPosted: false
};

// Cleanup quizzes older than 7 days
const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
for (const [id, data] of Object.entries(staticData.quizzes)) {
  if (Date.now() - data.createdAt > sevenDaysMs) {
    delete staticData.quizzes[id];
  }
}

// Pass threadId, parsed quiz fields, and normalized references forward
return [{
  json: {
    ...quiz,
    threadId,
    explanation: formattedExplanation,
    webReferences: normalizedWebRefs,
    sourceCitation: resolvedCitation
  }
}];

