  const v3 = mod(v * v * v);
  const v7 = mod(v3 * v3 * v);
  let x = mod(u * v3 * powMod(mod(u * v7), (P - 5n) / 8n));
  const check = mod(v * x * x);
  if (check === mod(-u)) x = mod(x * I);
  else if (check !== u) return null;
  if (x === 0n && sign === 1) return null;
  if (Number(x & 1n) !== sign) x = mod(-x);
  return [x, y];
}
function encodePoint([x, y]) {
  const b = bigIntToBytesLE(y);
  if (x & 1n) b[31] |= 0x80;
  return b;
}
function edAdd([x1, y1], [x2, y2]) {
  const a = mod((y1 - x1) * (y2 - x2));
  const b = mod((y1 + x1) * (y2 + x2));
  const c = mod(2n * D * x1 * x2 * y1 * y2);
  const d = mod(2n);
  const e = mod(b - a);
  const f = mod(d - c);
  const g = mod(d + c);
  const h = mod(b + a);
  return [mod(e * f * inv(f * g)), mod(g * h * inv(f * g))];
}
function edMul(pt, s) {
  let r = [0n, 1n], p = pt;
  while (s > 0n) { if (s & 1n) r = edAdd(r, p); p = edAdd(p, p); s >>= 1n; }
  return r;
}

function verifyEd25519(sigHex, msgBytes, pubHex) {
  if (!sigHex || sigHex.length !== 128 || !pubHex || pubHex.length !== 64) return false;
  const sig = hexToBytes(sigHex);
  const pub = hexToBytes(pubHex);
  const R = decodePoint(sig.slice(0, 32));
  const A = decodePoint(pub);
  const S = bytesToBigIntLE(sig.slice(32, 64));
  if (!R || !A || S >= L) return false;
  const hInput = new Uint8Array(64 + msgBytes.length);
  hInput.set(sig.slice(0, 32), 0);
  hInput.set(pub, 32);
  hInput.set(msgBytes, 64);
  const k = mod(bytesToBigIntLE(sha512(hInput)), L);
  const lhs = encodePoint(edMul([Bx, By], S));
  const rhs = encodePoint(edAdd(R, edMul(A, k)));
  for (let i = 0; i < 32; i++) if (lhs[i] !== rhs[i]) return false;
  return true;
}

// 1. Verify Discord Signature
const msgBytes = new TextEncoder().encode((timestamp || '') + rawBody);
const isValid = verifyEd25519(signature, msgBytes, PUBLIC_KEY_HEX);

if (!isValid) {
  return {
    json: {
      route: 'respond_now',
      statusCode: 401,
      responseBody: { error: 'Invalid request signature' }
    }
  };
}

const body = rawItem.body || JSON.parse(rawBody);

// 2. Reply to Discord Verification PING (type: 1)
if (body && body.type === 1) {
  return {
    json: {
      route: 'respond_now',
      statusCode: 200,
      responseBody: { type: 1 }
    }
  };
}

// Load saved quiz keys from Extract from File JSON output
const extracted = $('Extract keys').item.json;
const quizzes = (extracted && typeof extracted.data === 'object' && !Array.isArray(extracted.data))
  ? extracted.data
  : (extracted || {});

// 3. Handle Button / Dropdown Clicks (type: 3 — Path 2A)
if (body && body.type === 3) {
  const threadId = body.channel_id;
  const quizKey = quizzes[threadId] || null;

  if (!quizKey) {
    return {
      json: {
        route: 'respond_now',
        statusCode: 200,
        responseBody: {
          type: 4,
          data: {
            flags: 64,
            content: `⚠️ Key not found!\n• Clicked \`channel_id\`: \`${threadId}\`\n• Saved thread IDs in file: \`${JSON.stringify(Object.keys(quizzes))}\``
          }
        }
      }
    };
  }

  let selected = [];
  if (body.data.component_type === 2) {
    selected.push(body.data.custom_id.replace('quiz_opt_', ''));
  } else if (body.data.component_type === 3) {
    selected = body.data.values || [];
  }

  const userStr = selected.map(s => s.trim().toUpperCase()).sort().join(', ');
  const correctStr = String(quizKey.correctAnswer)
    .split(',')
    .map(s => s.trim().toUpperCase())
    .sort()
    .join(', ');

  const isCorrect = userStr === correctStr;
  const statusHeader = isCorrect
    ? `🎉 **Correct!** You chose **${userStr}**.`
    : `❌ **Not quite.** You chose **${userStr}**, while the correct answer is **${correctStr}**.`;

  const refsBlock = quizKey.webReferences ? `\n\n🔗 **References:**\n${quizKey.webReferences}` : '';

  return {
    json: {
      route: 'respond_now',
      statusCode: 200,
      responseBody: {
        type: 4,
        data: {
          flags: 64,
          content: `${statusHeader}\n\n💡 **Explanation:**\n${quizKey.explanation}${refsBlock}`
        }
      }
    }
  };
}

// 4. Handle Slash Commands (type: 2 — Path 2B: /ans)
if (body && body.type === 2 && body.data.name === 'ans') {
  const threadId = body.channel_id;
  const quizKey = quizzes[threadId] || null;
  const userText = body.data.options?.[0]?.value || '';
  const userId = body.member?.user?.id || body.user?.id;

  if (!quizKey) {
    return {
      json: {
        route: 'respond_now',
        statusCode: 200,
        responseBody: {
          type: 4,
          data: {
            flags: 64,
            content: "⚠️ Please run `/ans` inside an active quiz thread (this thread has no active answer key)."
          }
        }
      }
    };
  }

  return {
    json: {
      route: 'grade_short_answer',
      applicationId: body.application_id,
      interactionToken: body.token,
      userId,
      userText,
      question: quizKey.question,
      correctAnswer: quizKey.correctAnswer,
      explanation: quizKey.explanation
    }
  };
}

return {
  json: {
    route: 'respond_now',
    statusCode: 200,
    responseBody: { type: 1 }
  }
};

// Load existing keys if the file was found
let quizzes = {};
try {
  if ($input.item.binary?.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    quizzes = JSON.parse(buf.toString('utf8'));
  }
} catch (e) {
  quizzes = {};
}

// Grab the new quiz from Save Quiz Key
const newQuiz = $('Save Quiz Key').item.json;

// Normalize webReferences whether it arrives as a formatted string or an array
const normalizedWebRefs = Array.isArray(newQuiz.webReferences)
  ? newQuiz.webReferences.map(u => `• <${u}>`).join('\n')
  : (typeof newQuiz.webReferences === 'string' && newQuiz.webReferences.trim()
      ? newQuiz.webReferences
      : (Array.isArray(newQuiz.referenceUrls) ? newQuiz.referenceUrls.map(u => `• <${u}>`).join('\n') : ''));

quizzes[newQuiz.threadId] = {
  question: newQuiz.question,
  targetFormat: newQuiz.targetFormat,
  correctAnswer: newQuiz.correctAnswer,
  explanation: newQuiz.explanation,
  webReferences: normalizedWebRefs,
  sourceCitation: newQuiz.sourceCitation || 'Web Research',
  createdAt: Date.now(),
  publicPosted: false
};

// Clean up entries older than 7 days
const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
for (const [id, data] of Object.entries(quizzes)) {
  if (Date.now() - data.createdAt > sevenDaysMs) {
    delete quizzes[id];
  }
}

// Convert updated dictionary into a binary JSON file for Write File node
const base64Data = Buffer.from(JSON.stringify(quizzes, null, 2), 'utf8').toString('base64');
return [{
  json: {
    ...newQuiz,
    webReferences: normalizedWebRefs
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: 'application/json',
      fileName: 'quiz_keys.json'
    }
  }
}];

