const routerData = $('Router & Verifier').item.json;
const rawBody = $('Listen to Click').item.json.body || {};

// Combine all Gemini response parts (parts[0], parts[1], etc.)
const parts = $input.item.json.content?.parts || [];
const llmFeedback = parts.length
  ? parts.map(p => p.text || '').join('')
  : ($input.item.json.text || $input.item.json.output || '');

const privateMessage = [
  `📝 **Your Submitted Answer:**`,
  `> ${routerData.userText.replace(/\n/g, '\n> ')}`,
  ``,
  llmFeedback.trim(),
  ``,
  `⏳ *The official answer and full source breakdown will post publicly in this thread once the 3-hour window closes.*`
].join('\n');

const appId = routerData.applicationId || rawBody.application_id;
const token = routerData.interactionToken || rawBody.token;

// Single object return (required for "Run Once for Each Item" mode)
return {
  json: {
    url: `https://discord.com/api/v10/webhooks/${appId}/${token}/messages/@original`,
    payload: {
      content: privateMessage.slice(0, 1950)
    }
  }
};

const routerData = $('Router & Verifier').item.json;
const threadId = $('Listen to Click').item.json.body.channel_id;

const publicContent = [
  `💬 **<@${routerData.userId}> shared an answer:**`,
  `> ${routerData.userText.replace(/\n/g, '\n> ')}`
].join('\n');

return {
  json: {
    ...routerData,
    threadId,
    publicPostUrl: `https://discord.com/api/v10/channels/${threadId}/messages`,
    publicPostPayload: {
      content: publicContent.slice(0, 1950)
    }
  }
};
